const { execSync } = require('child_process');
const ExcelJS = require('exceljs');

async function main() {
  // Run tesseract OCR
  const ocrOutput = execSync('tesseract /workspace/testbed/images/invoice.png stdout 2>/dev/null', { encoding: 'utf-8' });

  // Split into non-empty lines
  const lines = ocrOutput.split('\n').filter(line => line.trim() !== '');

  // Create Excel workbook
  const workbook = new ExcelJS.Workbook();
  const sheet = workbook.addWorksheet('Invoice OCR');

  // Header
  sheet.getColumn(1).header = 'Extracted Text';
  sheet.getColumn(1).width = 40;
  sheet.getRow(1).getCell(1).value = 'Extracted Text';
  sheet.getRow(1).font = { bold: true };

  // Add each line as a row
  lines.forEach(line => {
    sheet.addRow([line]);
  });

  const outputPath = '/workspace/invoice_ocr.xlsx';
  await workbook.xlsx.writeFile(outputPath);
  console.log(`Excel file created: ${outputPath}`);
  console.log(`Rows written: ${lines.length}`);
  lines.forEach((l, i) => console.log(`  Row ${i + 2}: "${l}"`));
}

main().catch(console.error);
